/** Modules default on; copper pours default off. U18 is always instantiated. */
export function AM62ABoard({ flags: overrides = {} }: { flags?: Partial<ModuleFlags> }) {
  const flags = { ...defaultFlags, ...overrides }
  for (const module of requiredModules) flags[module] = true
  const routing = createRouting(flags)
  return <board width={84.99983} height={150.096728} thickness={1.29004} layers={12} pcbRelative schRelative routingDisabled schematicDisabled={!flags.renderSchematic} schMaxTraceDistance={0}>
    <Processor flags={flags} routing={routing} />
    <PowerInput flags={flags} routing={routing} />
    <PeripheralPower flags={flags} routing={routing} />
    <SystemPower flags={flags} routing={routing} />
    <Pmic flags={flags} routing={routing} />
    <PowerMonitor flags={flags} routing={routing} />
    <ProcessorSupport flags={flags} routing={routing} />
    <Lpddr4 flags={flags} routing={routing} />
    <M2 flags={flags} routing={routing} />
    <Emmc flags={flags} routing={routing} />
    <SdCard flags={flags} routing={routing} />
    <Ospi flags={flags} routing={routing} />
    <BoardId flags={flags} routing={routing} />
    <Ethernet1 flags={flags} routing={routing} />
    <Ethernet2 flags={flags} routing={routing} />
    <EthernetClock flags={flags} routing={routing} />
    <TestAutomation flags={flags} routing={routing} />
    <BootMode flags={flags} routing={routing} />
    <Xds110 flags={flags} routing={routing} />
    <Jtag flags={flags} routing={routing} />
    <UsbUart flags={flags} routing={routing} />
    <WakeGpmc flags={flags} routing={routing} />
    <Expansion flags={flags} routing={routing} />
    <McuHeader flags={flags} routing={routing} />
    <UsbHost flags={flags} routing={routing} />
    <UsbDrd flags={flags} routing={routing} />
    <UartSwitch flags={flags} routing={routing} />
    <Camera flags={flags} routing={routing} />
    <Audio flags={flags} routing={routing} />
    <IoExpander flags={flags} routing={routing} />
    <Hdmi flags={flags} routing={routing} />
    <Oscillator flags={flags} routing={routing} />
    <Reset flags={flags} routing={routing} />
    <CanWake flags={flags} routing={routing} />
    <TestPoints flags={flags} routing={routing} />
    <Mechanical flags={flags} routing={routing} />
    <BoardExtras flags={flags} routing={routing} />
    {flags.renderSchematic && <ReferenceSchematic flags={flags} />}
    <Connectivity flags={flags} />
    {flags.addPours && <CopperPours flags={flags} />}
  </board>
}

if (typeof circuit !== "undefined") circuit._featureMspSchematicTraceRouting = false;
export default function SelectedBoard() { return <AM62ABoard flags={{renderSchematic:true}} /> }
